INSERT INTO loads (id, load_title, load_description, load_image, normative, load_category, reliability_coefficient, status) VALUES
(1, 'Полезная нагрузка',
'Полезная нагрузка — это совокупность временных воздействий, возникающих в процессе эксплуатации здания и не относящихся к собственной массе конструкций. К данной категории относятся люди, мебель, оборудование, инженерные устройства и иные предметы, которые могут находиться на перекрытии. В отличие от постоянных нагрузок, полезная нагрузка обладает переменным характером: её величина и распределение могут изменяться во времени в зависимости от сценария использования помещения. В нормативных документах (СП 20.13330 «Нагрузки и воздействия») значения полезных нагрузок задаются в виде удельного веса на единицу площади перекрытия (кг/м²). Для учёта возможных неблагоприятных ситуаций к нормативным значениям применяется коэффициент надёжности γ, отражающий степень неопределённости и вариативности воздействия. В проектных расчётах полезная нагрузка является одной из ключевых величин, определяющих выбор сечения и материала несущих элементов перекрытия. Недооценка данного параметра может привести к деформациям или потере несущей способности конструкции, поэтому на стадии проектирования закладываются повышенные значения с учётом возможных перегрузок.',
'http://localhost:9000/rip/image2.png', 150, 'Временная', 1.1, NULL),

(2, 'Собственный вес перекрытия',
'Собственный вес перекрытия — это постоянная нагрузка, которая учитывает массу всех конструктивных элементов самого перекрытия. К ней относятся вес плит перекрытия, стяжки, утеплителя, звукоизоляции, чистового покрытия пола и других слоёв, входящих в конструкцию. Данная нагрузка всегда присутствует и не зависит от эксплуатации помещения, поэтому она относится к категории постоянных нагрузок. В расчётах собственный вес перекрытия задаётся в виде нормативного значения удельной массы на квадратный метр и учитывается с коэффициентом надёжности. Эта величина напрямую влияет на общую нагрузку на несущие конструкции здания и фундамент, поэтому её корректное определение является обязательным этапом проектирования.',
'http://localhost:9000/rip/image3.png', 400, 'Временная', 1.1, NULL),

(3, 'Нагрузка от перегородок',
'Нагрузка от перегородок — это постоянная нагрузка, создаваемая внутренними ненесущими стенами и перегородками, расположенными на перекрытии. Она учитывает массу материалов, из которых выполнены перегородки (кирпич, гипсокартон, газобетон, пеноблоки и т. д.), а также их протяжённость и толщину. В отличие от собственного веса перекрытия, эта нагрузка распределяется не по всей площади, а только в местах установки перегородок, однако при расчётах её принято приводить к условному распределению на квадратный метр. Так как перегородки являются частью строительной конструкции и не зависят от режима эксплуатации помещения, нагрузка от них относится к категории постоянных нагрузок. Правильный учёт данной величины важен для проверки несущей способности перекрытия и предотвращения его избыточного прогиба или повреждений.',
'http://localhost:9000/rip/image4.png', 75, 'Временная', 1.1, NULL),

(4, 'Снеговая нагрузка',
'Снеговая нагрузка — это временная климатическая нагрузка, возникающая из-за массы снежного покрова, скапливающегося на поверхности покрытия здания. Она зависит от толщины и плотности снега, а также от формы и угла наклона кровли, наличия парапетов, продуваемости и климатического района строительства. В отличие от постоянных нагрузок, снеговая нагрузка изменяется во времени: она может существенно возрастать в зимний период и практически исчезать в тёплое время года. При проектировании зданий нормативные значения снеговой нагрузки задаются строительными нормами и корректируются коэффициентами, учитывающими особенности конкретного объекта. Учёт снеговой нагрузки необходим для проверки прочности и жёсткости перекрытий и покрытия, так как её недооценка может привести к деформациям или разрушению конструкций под действием избыточного веса снега.',
'http://localhost:9000/rip/image5.png', 180, 'Временная', 1.1, NULL),

(5, 'Нагрузка от оборудования',
'Нагрузка от оборудования — это временная нагрузка, создаваемая установленными в помещении машинами, приборами, инженерными установками и другими стационарными или передвижными устройствами. Масса оборудования может оказывать как равномерно распределённое воздействие на перекрытие (например, при расстановке легких приборов или мебели), так и сосредоточенное — в местах установки тяжёлых станков, баков, кондиционных агрегатов или серверных стоек. В зависимости от характера эксплуатации помещения нагрузка от оборудования может существенно варьироваться. В проектных расчётах её учитывают как временную нагрузку, так как состав и расположение оборудования в процессе эксплуатации здания могут изменяться. При этом для тяжёлого и стационарного оборудования нередко предусматриваются специальные усиления перекрытий или отдельные фундаментные опоры. Правильный учёт данной нагрузки позволяет обеспечить надёжную работу перекрытий, снизить риск деформаций и повреждений, а также повысить безопасность эксплуатации здания.',
'http://localhost:9000/rip/image6.png', 180, 'Временная', 1.1, NULL);
